/* ============================================================
   DATA LAYER — swap this object for a live API response.
   Every component below only renders this data; none of the
   race/energy logic lives in the UI.
   ============================================================ */

function buildForecast(currentEnergy, attackCost, lapsRemaining) {
  const rows = [];
  const burn = (currentEnergy - 4) / lapsRemaining;
  for (let i = 0; i <= lapsRemaining; i++) {
    rows.push({
      lap: 32 + i,
      Current: Math.max(0, +(currentEnergy - burn * i).toFixed(1)),
      Attack: Math.max(0, +(currentEnergy - attackCost - burn * 0.9 * i).toFixed(1)),
      Save: Math.max(0, +(currentEnergy - burn * 0.7 * i).toFixed(1)),
    });
  }
  return rows;
}

