/* ============================================================
   DESIGN TOKENS
   ============================================================ */

const C = {
  void: "#0B0D12",
  textPrimary: "#F4F2ED",
  textMuted: "#9AA0AE",
  glassFill: "rgba(255,255,255,0.055)",
  glassFillRaised: "rgba(255,255,255,0.09)",
  glassBorder: "rgba(255,255,255,0.14)",
  amberGlow: "#FF9F45",
  tealGlow: "#3ED9A8",
  go: "#34D399",
  caution: "#FBBF6B",
  stop: "#FB7185",
};

const STATUS_COLOR = { go: C.go, caution: C.caution, stop: C.stop };

const fontImport =
  "@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');";

/* ============================================================
   PRIMITIVES
   ============================================================ */

function Glass({ children, style, raised = false, glow }) {
  return (
    <div
      style={{
        background: raised ? C.glassFillRaised : C.glassFill,
        border: `1px solid ${glow ? glow + "55" : C.glassBorder}`,
        borderRadius: 20,
        backdropFilter: "blur(22px)",
        WebkitBackdropFilter: "blur(22px)",
        boxShadow: glow
          ? `0 0 0 1px ${glow}22, 0 20px 60px -20px ${glow}55, 0 1px 0 rgba(255,255,255,0.06) inset`
          : "0 20px 50px -25px rgba(0,0,0,0.6), 0 1px 0 rgba(255,255,255,0.05) inset",
        padding: "22px 24px",
        ...style,
      }}
    >
      {children}
    </div>
  );
}

function Eyebrow({ children, color = C.textMuted }) {
  return (
    <div style={{ fontSize: 12, fontWeight: 700, letterSpacing: "0.06em", color, marginBottom: 12, textTransform: "uppercase" }}>
      {children}
    </div>
  );
}

function Chip({ label, value, valueColor = C.textPrimary }) {
  return (
    <div
      style={{
        background: C.glassFillRaised,
        border: `1px solid ${C.glassBorder}`,
        borderRadius: 14,
        padding: "10px 14px",
      }}
    >
      <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: "0.06em", color: C.textMuted, marginBottom: 4, textTransform: "uppercase" }}>
        {label}
      </div>
      <div style={{ fontSize: 20, fontWeight: 700, color: valueColor }}>{value}</div>
    </div>
  );
}

function ReasonList({ items, color = C.go }) {
  return (
    <ul style={{ listStyle: "none", margin: 0, padding: 0, display: "grid", gap: 9 }}>
      {items.map((it) => (
        <li key={it} style={{ display: "flex", alignItems: "center", gap: 9, fontSize: 14, color: C.textPrimary }}>
          <span style={{
            width: 20, height: 20, borderRadius: 999, background: `${color}22`,
            display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0,
          }}>
            <Check size={12} color={color} strokeWidth={3} />
          </span>
          {it}
        </li>
      ))}
    </ul>
  );
}

